import type {Config} from '@docusaurus/types';
import type * as Preset from '@docusaurus/preset-classic';
import {copyFile, mkdir} from 'node:fs/promises';
import path from 'node:path';
import type {LoadContext, Plugin, PluginConfig, RouteConfig} from '@docusaurus/types';
import {withProductSite} from '@beyond10x/docs-system/product-site';

// Pages under docs/reference/ and docs/examples/, and the files under data/, are generated by
// `modelspec-docs generate`; everything else is written by hand.

// The pitch deck is one self-contained HTML file in the repository, docs/pitch/index.html. The
// build serves it at /modelspec/pitch/ from that file, so there is no second copy to drift.
const PITCH_DECK = path.resolve(__dirname, '../docs/pitch/index.html');

function pitchDeck(): Plugin {
  return {
    name: 'modelspec-pitch-deck',
    getPathsToWatch: () => [PITCH_DECK],
    async postBuild({outDir}) {
      const target = path.join(outDir, 'pitch', 'index.html');
      await mkdir(path.dirname(target), {recursive: true});
      await copyFile(PITCH_DECK, target);
    },
  };
}

